function y({registerIndicator:M,nulls:d}){M({id:"oa-trim",name:"TRIM: Trimmed Mean Moving Average",category:"Statistics",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:20,min:3,max:5e3,step:1},{key:"trimPct",type:"number",label:"Trim %",default:10,min:0,max:49,step:1,tooltip:"Percentage trimmed from each tail. 0=SMA, 50=Median"}],plots:[{key:"trim",type:"line",title:"TRIM",style:{color:"#ffeb3b",lineWidth:2}}],calc(m,l){const e=Math.max(3,Math.floor(Number(l.period)||20)),c=Number(l.trimPct),h=Number.isFinite(c)?Math.min(49,Math.max(0,Math.floor(c))):10;let r=Math.max(Math.trunc(e*h/100),0),i=e-2*r;i<1&&(i=1,r=Math.trunc((e-1)/2));const s=m.length,u=new Array(s).fill(NaN),n=new Array(e);for(let o=0;o<s;o++){for(let t=0;t<e;t++){const a=o-t,p=a>=0?m[a].close:NaN;n[t]=Number.isFinite(p)?p:0}n.sort((t,a)=>t-a);let f=0;for(let t=r;t<r+i;t++)f+=n[t];u[o]=f/i}return{trim:d(u)}}})}export{y as default};
